-- One-time fix: pre-create target table for offline file ingestion task 6.
-- Addax postgresqlwriter checks table column metadata in init() BEFORE preSql
-- runs in prepare(), so the platform's CREATE TABLE IF NOT EXISTS in preSql can
-- never create a brand-new table. Create it once here, as role biadmin (owner),
-- with the exact DDL the platform generates; later runs are idempotent.
SET ROLE biadmin;
CREATE TABLE IF NOT EXISTS "ods_project_subject_domain_v2" ("id" bigserial primary key, "project_no" varchar(500), "subsystem" varchar(500), "node_task" varchar(500), "plan_start_date" varchar(500), "plan_date" varchar(500), "plan_week" varchar(500), "deliverable" varchar(500), "node_type" varchar(500), "owner" varchar(500), "dept" varchar(500), "dept_leader" varchar(500), "completion_status" varchar(500), "collab_dept" varchar(500), "supervisor_dept" varchar(500), "delay_expected_date" varchar(500), "incomplete_reason" varchar(500), "risk_level" varchar(500), "risk_content" varchar(500), "delay_impact" varchar(500), "actual_start_date" varchar(500), "actual_date" varchar(500), "actual_week" varchar(500), "institute_leader" varchar(500), "source" varchar(500), "original_plan_date" varchar(500), "delay_days_changed" varchar(500), "delay_days_unchanged" varchar(500), "delay_applied" varchar(500), "project_manager" varchar(500), "last_update_time" varchar(500), "last_update_week" varchar(500), "filled_by" varchar(500), "highlight" varchar(500), "_dts_source_system" VARCHAR(500) DEFAULT 'ods_project_subject_domain_v2.xlsx', "_dts_source_table" VARCHAR(500) DEFAULT 'ods_project_subject_domain_v2.xlsx', "_dts_import_time" TIMESTAMP DEFAULT timezone('Asia/Shanghai', now()), "_dts_batch_id" VARCHAR(500), "_dts_execution_id" VARCHAR(500), "_dts_task_id" VARCHAR(500) DEFAULT '6', "_dts_source_file" VARCHAR(500) DEFAULT 'ods_project_subject_domain_v2.xlsx', "_dts_source_sheet" VARCHAR(500), "_dts_file_hash" VARCHAR(500), "_dts_row_number" INTEGER);
RESET ROLE;
